const SCRYFALL_BASE = 'https://api.scryfall.com';
const MIN_REQUEST_INTERVAL_MS = 100;
const SET_LIST_TTL_MS = 24 * 60 * 60 * 1000; // 24 hours
const ATTEMPT_TIMEOUT_MS = 5000;

/**
 * Read this package's own version from package.json at load time. A static
 * JSON import is not an option: package.json sits outside the TypeScript
 * rootDir (src/), so tsc cannot emit it alongside the compiled output. Both
 * the source tree (src/services/) and the build output (dist/services/) sit
 * two levels below the package root ΓÇö and the Docker runtime image preserves
 * that layout ΓÇö so the same relative specifier resolves under vitest and in
 * production alike.
 */
function readPackageVersion(): string {
  try {
    const nodeRequire = createRequire(import.meta.url);
    const pkg = nodeRequire('../../package.json') as { version?: unknown };
    if (typeof pkg.version === 'string' && pkg.version.length > 0) {
      return pkg.version;
    }
  } catch {
    // Fall through to the placeholder version below.
  }
  return '0.0.0';
}

/**
 * Scryfall asks every client to identify itself with a descriptive
 * User-Agent (application name and version, plus a contact URL) and to send
 * an Accept header on every request, and may block clients that omit either.
 */
const SCRYFALL_USER_AGENT = `${PROJECT_NAME}/${readPackageVersion()} (+${PROJECT_REPOSITORY})`;

